'use strict';

/** Single error type for everything this package throws. */
class MediaDownloaderError extends Error {
  /**
   * @param {string} message
   * @param {object} [details]
   * @param {string} [details.code] Machine-readable code, e.g. RATE_LIMITED.
   * @param {number} [details.status] HTTP status returned by the API.
   * @param {string} [details.endpoint] Endpoint that was called.
   */
  constructor(message, details = {}) {
    super(message);
    this.name = 'MediaDownloaderError';
    this.code = details.code || 'ERROR';
    this.status = details.status;
    this.endpoint = details.endpoint;
  }
}

const ERROR_CODES = Object.freeze({
  INVALID_URL: 'INVALID_URL',
  UNKNOWN_ENDPOINT: 'UNKNOWN_ENDPOINT',
  NETWORK: 'NETWORK',
  TIMEOUT: 'TIMEOUT',
  BAD_JSON: 'BAD_JSON',
  RATE_LIMITED: 'RATE_LIMITED',
  UPSTREAM: 'UPSTREAM',
  NO_MEDIA: 'NO_MEDIA',
  RESOLVE_FAILED: 'RESOLVE_FAILED',
});

module.exports = { MediaDownloaderError, ERROR_CODES };
